<?php if ( ! defined( 'ABSPATH' ) ) { exit; } get_header(); while(have_posts()): the_post(); $country_id=(int)get_post_meta(get_the_ID(),'_nvconsult_country_id',true); $programs=new WP_Query(array('post_type'=>'nvconsult_program','post_status'=>'publish','posts_per_page'=>-1,'meta_key'=>'_nvconsult_institution_id','meta_value'=>get_the_ID())); ?>
<main class="single-shell"><section class="single-hero"><h1><?php the_title(); ?></h1><?php if($country_id): ?><p><a class="btn-outline" href="<?php echo esc_url( get_permalink( $country_id ) ); ?>"><?php echo esc_html( get_the_title( $country_id ) ); ?></a></p><?php endif; ?></section><div class="single-layout"><div class="content-card"><?php the_content(); ?></div><aside class="single-sidebar content-card"><h3><?php esc_html_e( 'Programs', 'nvconsult-theme-v2' ); ?></h3><?php if($programs->have_posts()): ?><ul><?php while($programs->have_posts()): $programs->the_post(); ?><li><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></li><?php endwhile; wp_reset_postdata(); ?></ul><?php else: ?><p><?php esc_html_e( 'No programs linked yet.', 'nvconsult-theme-v2' ); ?></p><?php endif; ?></aside></div></main>
<?php endwhile; get_footer(); ?>
